import math

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def sequence_lcm(k, n):
    """Calculates x_k = lcm(k, k+1, ..., k+n-1)"""
    if n == 0:
        return 1
    result = k
    for i in range(1, n):
        result = lcm(result, k + i)
    return result

def check_for_equality(n, max_k):
    print(f"--- Investigating n = {n} ---")
    count_equal = 0
    for k in range(1, max_k + 1):
        x_k = sequence_lcm(k, n)
        x_k_plus_1 = sequence_lcm(k + 1, n)

        if x_k_plus_1 == x_k:
            count_equal += 1
            print(f"Equality found at k={k}: x_k = x_{k+1} = {x_k}")
        # Optional: Track general growth trend
        # elif x_k_plus_1 < x_k:
        #     print(f"DECREASE detected at k={k}: x_k = {x_k}, x_{k+1} = {x_k_plus_1}")
    print(f"Total equalities found for n={n} up to k={max_k}: {count_equal}")

# Search for n >= 3
max_k_to_check = 50  # Limiting search space due to rapid growth of LCM
for n in range(3, 8): # Check n=3, 4, 5, 6, 7
    check_for_equality(n, max_k_to_check)

