import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def calculate_x_k(n, k_max):
    results = {}
    for k in range(1, k_max + 1):
        numbers = list(range(k, k + n))
        x_k = lcm_list(numbers)
        results[k] = x_k
    return results

