import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def lcm_of_range(start, end):
    return reduce(lcm, range(start, end + 1))

n = 5
max_k = 10  # Check up to k=10 to verify the trend

x_values = {}
for k in range(1, max_k + 1):
    # x_k = lcm(k, k+1, ..., k+n-1)
    end = k + n - 1
    x_values[k] = lcm_of_range(k, end)

print("Sequence terms for n=5 (k=1 to k=10):")
for k in range(1, max_k + 1):
    print(f"x_{k} = {x_values[k]}")

# Check the condition x_{k+1} > x_k for k >= 2
print("\nChecking if x_{k+1} > x_k for k >= 2:")
failures = []
for k in range(2, max_k):
    if x_values[k+1] <= x_values[k]:
        failures.append(k)

if not failures:
    print("No failure found for k=2 through k=9.")
else:
    print(f"Failures found at k = {failures}")
